const HOST = "51.79.226.200", PORT = 22, USER = "root";
const GUARD = 'hostname -I | tr " " "\\n" | grep -qx 51.79.226.200 || { echo "WRONG_HOST_ABORT"; exit 87; }; ';

async function getPassword(){
