}
function exec(conn, command, timeoutMs=600000){
  return new Promise((resolve,reject)=>{
    conn.exec(command,(err,stream)=>{
      if(err)return reject(err);
      let out="",errout="",done=false;
      const t=setTimeout(()=>{if(!done){done=true;try{stream.close()}catch{};reject(new Error("timeout"))}},timeoutMs);
      stream.on("close",code=>{if(done)return;done=true;clearTimeout(t);resolve({code,stdout:out,stderr:errout})})
            .on("data",d=>out+=d).stderr.on("data",d=>errout+=d);
    });
  });
}

const mode = process.argv[2];
const pw = await getPassword();
if(mode==="exec"){
  const cmd = fs.readFileSync(process.argv[3],"utf8");
  const conn = await connect(pw);
  const r = await exec(conn, GUARD + cmd, Number(process.argv[4]||600000));
  conn.end();
  process.stdout.write(r.stdout);
  if(r.stderr) process.stderr.write("\n[STDERR]\n"+r.stderr);
  console.log("\n[EXIT] "+r.code);
  process.exit(r.code===0?0:(r.code||1));
} else if(mode==="upload"){
  // upload local -> remote (args: localPath remotePath)
  const sftp = new SftpClient();
  await sftp.connect({host:HOST,port:PORT,username:USER,password:pw,readyTimeout:15000});
  await sftp.put(process.argv[3], process.argv[4]);
  await sftp.end();
  console.log("[UPLOADED] "+process.argv[4]);
} else if(mode==="download"){
  const sftp = new SftpClient();
  await sftp.connect({host:HOST,port:PORT,username:USER,password:pw,readyTimeout:15000});
  await sftp.get(process.argv[3], process.argv[4]);
  await sftp.end();
  console.log("[DOWNLOADED] "+process.argv[4]);
}
