29	    /// <summary>Derive a client's VIP tier from the admin-configured thresholds.</summary>
30	    private static string ComputeVipTier(GlobalSettings s, decimal lifetime, int attended)
31	    {
32	        if (!s.EnableVipProgram) return "";
33	        if (lifetime >= s.SuperVipMinimumSpend && attended >= s.SuperVipMinimumClasses) return "SUPER_VIP";
34	        if (lifetime >= s.VipMinimumSpend) return "VIP";
