38	    [HttpGet]
39	    public async Task<IActionResult> GetAll([FromQuery] string? search, [FromQuery] string? sort)
40	    {
41	        var clients = await _clientService.SearchClientsAsync(search ?? "");
42	        var settings = await _settingsService.GetAsync();
43	        var counts = await _clientService.GetCheckedInCountsAsync();
44	        var credits = await _clientService.GetActiveCreditsByClientAsync();
45	        // Only compute per-client recency when the caller asks to rank by it
46	        // (the top-bar quick search), so the default list path stays unchanged.
47	        var lastVisit = string.Equals(sort, "recent", StringComparison.OrdinalIgnoreCase)
48	            ? await _clientService.GetLastVisitByClientAsync()
49	            : null;
50	        var dtos = clients.Select(c =>
51	        {
52	            var attended = counts.GetValueOrDefault(c.Id ?? "", 0);
53	            var cr = credits.GetValueOrDefault(c.Id ?? "", (0, 0, 0));
54	            return new ClientDto
55	            {
56	                id = c.Id,
57	                name = c.FullName,
58	                email = c.Email,
59	                phone = c.PhoneNumber,
60	                phoneCountryCode = c.PhoneCountryCode,
61	                preferredContactPlatform = c.ContactPlatform,
62	                country = c.CountryOfOrigin,
63	                notes = c.InternalNotes,
64	                medicalHistory = c.MedicalHistory,
65	                tags = c.Tags,
66	                partnerCode = c.ReferredByPartnerId,
67	                dateOfBirth = c.DateOfBirth,
68	                createdAt = c.CreatedAt,
69	                firstVisitDate = c.FirstVisitDate,
70	                lifetimeValue = c.LifetimeValue,
71	                attendedClasses = attended,
72	                vipTier = ComputeVipTier(settings, c.LifetimeValue, attended),
73	                groupCredits = cr.Item1,
74	                matCredits = cr.Item2,
75	                privateCredits = cr.Item3,
76	            };
77	        });
78	
79	        if (lastVisit is not null)
80	        {
81	            // Rank recently-active clients first, then by total visits, then name.
82	            dtos = dtos
83	                .OrderByDescending(d => lastVisit.TryGetValue(d.id ?? "", out var lv) ? lv : DateTime.MinValue)
84	                .ThenByDescending(d => d.attendedClasses)
85	                .ThenBy(d => d.name);
