134	    {
135	        var c = await _clientService.GetClientByIdAsync(id);
136	        if (c == null) return NotFound();
137	        if (string.IsNullOrWhiteSpace(c.Email))
138	            return BadRequest(new { error = "This client has no email on file — add one before sending an invite." });
139	
140	        var acct = await _customerAuth.GetAccountByClientIdAsync(id);
141	        if (acct is { EmailVerified: true })
142	            return Conflict(new { error = "This client already has an active account." });
143	
144	        // resend:true so a pending (invited-but-not-activated) account gets a fresh link.
145	        var result = await _customerAuth.SendActivationInvitesAsync(id, null, resend: true);
146	        if (result.NoEmail > 0)
