202	            ContactPlatform = dto.preferredContactPlatform ?? "NONE",
203	            CountryOfOrigin = dto.country ?? "Vietnam",
204	            InternalNotes = dto.notes,
205	            MedicalHistory = dto.medicalHistory,
206	            Tags = dto.tags ?? new(),
207	            DateOfBirth = dto.dateOfBirth,
208	            // Normalise empty / whitespace partner id to null — the Mongo
209	            // serializer treats this field as an ObjectId and an empty
210	            // string would otherwise throw a BsonSerializationException
211	            // at insert-time ("'' is not a valid 24 digit hex string").
212	            ReferredByPartnerId = NormalisePartnerId(dto.partnerCode),
213	            // Lifecycle metrics are read-only over the wire; the importer
214	            // and downstream aggregators are the only writers. We
215	            // deliberately do not honour these on inbound bodies so an
216	            // operator can't accidentally overwrite computed stats.
217	        };
218	        var created = await _clientService.CreateClientAsync(client);
219	        dto.id = created.Id;
