223	    [HttpPut("{id}")]
224	    public async Task<IActionResult> Update(string id, [FromBody] ClientDto dto)
225	    {
226	        // Preserve server-managed lifecycle metrics across PUT — the
227	        // inbound DTO doesn't carry authoritative FirstVisitDate /
228	        // LifetimeValue and a naive overwrite would zero them.
229	        var existing = await _clientService.GetClientByIdAsync(id);
230	        if (existing == null) return NotFound();
231	
232	        var client = new Client
233	        {
234	            Id = id,
235	            FullName = dto.name,
236	            Email = dto.email,
237	            PhoneNumber = dto.phone,
238	            PhoneCountryCode = dto.phoneCountryCode,
239	            ContactPlatform = dto.preferredContactPlatform ?? "NONE",
240	            CountryOfOrigin = dto.country ?? "Vietnam",
241	            InternalNotes = dto.notes,
242	            MedicalHistory = dto.medicalHistory,
243	            // Preserve the onboarding-captured referral source across edits —
244	            // the client-edit form doesn't expose it, so fall back to the
245	            // stored value rather than nulling it out. (An explicit non-empty
246	            // value on the DTO still wins, allowing a future form to edit it.)
247	            ReferralSource = string.IsNullOrWhiteSpace(dto.referralSource) ? existing.ReferralSource : dto.referralSource,
248	            Tags = dto.tags ?? new(),
249	            DateOfBirth = dto.dateOfBirth,
250	            // Mirrors Create() — see normalisation comment above.
251	            ReferredByPartnerId = NormalisePartnerId(dto.partnerCode),
252	            // Carry lifecycle metrics forward from the existing document
253	            // so client-managed edits don't clobber server-computed state.
254	            FirstVisitDate = existing.FirstVisitDate,
255	            LifetimeValue = existing.LifetimeValue,
256	            CreatedAt = existing.CreatedAt,
257	            // ── Preserve server-managed state across a profile save ──
258	            // UpdateClientAsync does a full document REPLACE, so any field not
259	            // copied here is silently reset to its default. Before this, saving
260	            // a client from the edit form wiped their retention opt-out (re-
261	            // subscribing an unsubscribed client), their unsubscribe token, and
262	            // the win-back / birthday / VIP-notified throttles. The email-
263	            // subscription toggle is edited through its own dedicated endpoint
264	            // (SetEmailSubscription), never via this generic PUT.
265	            RetentionRemindersOptedOut = existing.RetentionRemindersOptedOut,
266	            UnsubscribeToken = existing.UnsubscribeToken,
267	            WinBackEmailSentAt = existing.WinBackEmailSentAt,
268	            LastBirthdayEmailSentYear = existing.LastBirthdayEmailSentYear,
269	            VipTierNotified = existing.VipTierNotified,
270	            IsStudioRentalProfile = existing.IsStudioRentalProfile,
271	            StudioRentalStaffId = existing.StudioRentalStaffId,
272	        };
273	        await _clientService.UpdateClientAsync(id, client);
274	        return Ok();
275	    }
