277	    /// <summary>
278	    /// Toggle a client's email subscription (retention / marketing check-in
279	    /// emails) from the admin profile page. Sets the entity's
280	    /// <c>RetentionRemindersOptedOut</c> to the inverse of <c>subscribed</c> via a
281	    /// targeted single-field update — it does NOT replace the rest of the
282	    /// document, so it is safe to call independently of the full profile save.
283	    /// </summary>
284	    [HttpPut("{id}/email-subscription")]
285	    public async Task<IActionResult> SetEmailSubscription(string id, [FromBody] EmailSubscriptionUpdateDto body)
286	    {
287	        if (body == null) return BadRequest(new { error = "Missing body." });
288	        var existing = await _clientService.GetClientByIdAsync(id);
289	        if (existing == null) return NotFound();
290	        await _clientService.SetEmailSubscribedAsync(id, body.subscribed);
291	        return Ok(new { id, emailSubscribed = body.subscribed });
292	    }
293	
294	    /// <summary>
295	    /// Coerces an inbound partner-id string into a value safe for the Mongo
296	    /// <c>ObjectId</c> serializer:
297	    /// <list type="bullet">
298	    ///   <item><c>null</c>, empty, or whitespace → <c>null</c> (unlinked).</item>
299	    ///   <item>Any non-blank value is passed through verbatim. If the caller
300	    ///   sends a non-ObjectId string the serializer will still reject it at
301	    ///   insert time — we don't try to repair garbage here, only the
302	    ///   universally-common "empty form field" case.</item>
303	    /// </list>
304	    /// </summary>
305	    private static string? NormalisePartnerId(string? raw)
306	        => string.IsNullOrWhiteSpace(raw) ? null : raw.Trim();
307	}
