309	/// <summary>Request body for <c>PUT api/client/{id}/email-subscription</c>.</summary>
310	public class EmailSubscriptionUpdateDto
311	{
312	    /// <summary>True to (re)subscribe the client to check-in emails, false to opt out.</summary>
313	    public bool subscribed { get; set; } = true;
314	}
