20	    public ClientService(MongoDbContext dbContext, IAuditLogger audit, INotificationPublisher notifications)
21	    {
22	        _clients = dbContext.GetCollection<Client>("Clients");
23	        _attendances = dbContext.GetCollection<Attendance>("Attendances");
24	        _packages = dbContext.GetCollection<ClientPackage>("ClientPackages");
