30	    /// <summary>
31	    /// Active remaining credits per client, split into (group, mat, private).
32	    /// MIXED packages count as group (they're usable for group/mat classes).
33	    /// </summary>
34	    public async Task<Dictionary<string, (int group, int mat, int priv)>> GetActiveCreditsByClientAsync()
35	    {
36	        var packages = await _packages.Find(p => p.CreditsRemaining > 0).ToListAsync();
37	        var result = new Dictionary<string, (int group, int mat, int priv)>();
38	        foreach (var grp in packages.GroupBy(p => p.ClientId))
39	        {
40	            if (string.IsNullOrEmpty(grp.Key)) continue;
41	            int g = 0, m = 0, pr = 0;
42	            foreach (var p in grp)
43	            {
44	                switch ((p.Format ?? "").ToUpperInvariant())
45	                {
46	                    case "MAT": m += p.CreditsRemaining; break;
47	                    case "PRIVATE": pr += p.CreditsRemaining; break;
48	                    default: g += p.CreditsRemaining; break; // GROUP, MIXED, other
49	                }
50	            }
51	            result[grp.Key] = (g, m, pr);
52	        }
53	        return result;
54	    }
55	
56	    /// <summary>Checked-in class count for one client (drives the Super VIP tier).</summary>
57	    public async Task<int> GetCheckedInCountAsync(string clientId) =>
58	        (int)await _attendances.CountDocumentsAsync(a => a.ClientId == clientId && a.Status == "CHECKED_IN");
59	
60	    /// <summary>Checked-in class counts for every client in one aggregation (clientId → count).</summary>
61	    public async Task<Dictionary<string, int>> GetCheckedInCountsAsync()
62	    {
63	        var grouped = await _attendances.Aggregate()
64	            .Match(Builders<Attendance>.Filter.Eq(a => a.Status, "CHECKED_IN"))
65	            .Group(a => a.ClientId, g => new { ClientId = g.Key, Count = g.Count() })
66	            .ToListAsync();
67	        return grouped
68	            .Where(x => !string.IsNullOrEmpty(x.ClientId))
69	            .ToDictionary(x => x.ClientId!, x => x.Count);
70	    }
71	
72	    /// <summary>
73	    /// Most recent visit (checked-in/arrived attendance) per client — used to rank
74	    /// quick-search results so recently-active clients surface first.
75	    /// </summary>
76	    public async Task<Dictionary<string, DateTime>> GetLastVisitByClientAsync()
77	    {
78	        var grouped = await _attendances.Aggregate()
79	            .Match(Builders<Attendance>.Filter.In(a => a.Status, new[] { "CHECKED_IN", "ARRIVED" }))
80	            .Group(a => a.ClientId, g => new { ClientId = g.Key, Last = g.Max(a => a.BookedAt) })
81	            .ToListAsync();
82	        return grouped
83	            .Where(x => !string.IsNullOrEmpty(x.ClientId))
84	            .ToDictionary(x => x.ClientId!, x => x.Last);
85	    }
