97	    public async Task<IEnumerable<Client>> SearchClientsAsync(string query)
98	    {
99	        if (string.IsNullOrWhiteSpace(query)) return await GetAllClientsAsync();
100	
101	        var digitsOnly = new string(query.Where(char.IsDigit).ToArray());
102	
103	        var filterBuilder = Builders<Client>.Filter;
104	        var filter = filterBuilder.Or(
105	            filterBuilder.Regex(c => c.FullName, new MongoDB.Bson.BsonRegularExpression(query, "i")),
106	            filterBuilder.Regex(c => c.Email, new MongoDB.Bson.BsonRegularExpression(query, "i")),
107	            filterBuilder.Regex(c => c.PhoneNumber, new MongoDB.Bson.BsonRegularExpression(query, "i")),
108	            string.IsNullOrEmpty(digitsOnly)
109	                ? filterBuilder.Where(_ => false)
110	                : filterBuilder.Regex(c => c.PhoneNumber, new MongoDB.Bson.BsonRegularExpression(digitsOnly, "i"))
111	        );
112	
113	        filter &= filterBuilder.Eq(c => c.IsStudioRentalProfile, false);
114	        return await _clients.Find(filter).ToListAsync();
115	    }
