148	    public async Task SetEmailSubscribedAsync(string id, bool subscribed)
149	    {
150	        // Targeted single-field update — never a full ReplaceOne — so the client's
151	        // other state is untouched. "Subscribed" is the inverse of the opt-out flag.
152	        await _clients.UpdateOneAsync(
153	            c => c.Id == id,
154	            Builders<Client>.Update.Set(c => c.RetentionRemindersOptedOut, !subscribed));
