156	
157	    public async Task UpdateClientAsync(string id, Client client)
158	    {
159	        var existing = await _clients.Find(c => c.Id == id).FirstOrDefaultAsync();
160	
161	        client.Id = id;
162	        await _clients.ReplaceOneAsync(c => c.Id == id, client);
163	
164	        if (existing is not null)
165	        {
166	            var changedBefore = new Dictionary<string, object?>();
167	            var changedAfter = new Dictionary<string, object?>();
168	
169	            if (existing.FullName != client.FullName)
170	            {
171	                changedBefore["FullName"] = existing.FullName;
172	                changedAfter["FullName"] = client.FullName;
173	            }
174	            if (existing.Email != client.Email)
175	            {
176	                changedBefore["Email"] = existing.Email;
177	                changedAfter["Email"] = client.Email;
178	
179	                // Keep the customer's LOGIN account email in sync with the CRM
180	                // email — otherwise editing a client's email here silently leaves
181	                // the customer logging in with the old address ("invalid login").
182	                await SyncAccountEmailAsync(id, client.Email);
183	            }
184	            if (existing.PhoneNumber != client.PhoneNumber || existing.PhoneCountryCode != client.PhoneCountryCode)
185	            {
186	                changedBefore["Phone"] = $"{existing.PhoneCountryCode}{existing.PhoneNumber}";
187	                changedAfter["Phone"] = $"{client.PhoneCountryCode}{client.PhoneNumber}";
188	            }
189	            if (existing.DateOfBirth != client.DateOfBirth)
190	            {
191	                changedBefore["DateOfBirth"] = existing.DateOfBirth;
192	                changedAfter["DateOfBirth"] = client.DateOfBirth;
193	            }
194	
195	            if (changedBefore.Count > 0)
196	            {
197	                await _audit.LogAsync(
198	                    action: "PII_UPDATE",
199	                    entityType: "Client",
200	                    entityId: id,
201	                    entityLabel: client.FullName,
202	                    before: changedBefore,
203	                    after: changedAfter);
204	            }
205	        }
206	    }
207	
208	    /// <summary>
209	    /// Propagates a client's new email to its linked login account(s) so the
210	    /// customer can still sign in. Skips (leaves login email unchanged) if the
211	    /// new email is blank or already belongs to a DIFFERENT account, to avoid
212	    /// creating a duplicate-login conflict.
213	    /// </summary>
214	    private async Task SyncAccountEmailAsync(string clientId, string? newEmail)
215	    {
216	        if (string.IsNullOrWhiteSpace(newEmail)) return;
217	        var email = newEmail.Trim().ToLowerInvariant();
218	
219	        var conflict = await _accounts.CountDocumentsAsync(
220	            a => a.Email == email && a.ClientId != clientId);
221	        if (conflict > 0) return;
222	
223	        await _accounts.UpdateManyAsync(
224	            a => a.ClientId == clientId,
225	            Builders<CustomerAccount>.Update
226	                .Set(a => a.Email, email)
227	                .Set(a => a.UpdatedAt, DateTime.UtcNow));
228	    }
229	
230	    public async Task<Client?> FindByPhoneOrEmailAsync(string phone, string? email)
231	    {
232	        if (!string.IsNullOrWhiteSpace(phone))
233	        {
234	            var byPhone = await _clients.Find(c => c.PhoneNumber == phone && !c.IsStudioRentalProfile).FirstOrDefaultAsync();
235	            if (byPhone != null) return byPhone;
236	
237	            if (phone.StartsWith('+'))
238	            {
239	                var (cc, national) = PhoneSplitter.Split(phone);
240	                if (cc != null && !string.IsNullOrEmpty(national))
241	                {
242	                    byPhone = await _clients
243	                        .Find(c => c.PhoneCountryCode == cc && c.PhoneNumber == national && !c.IsStudioRentalProfile)
244	                        .FirstOrDefaultAsync();
245	                    if (byPhone != null) return byPhone;
246	                }
247	            }
248	        }
249	
250	        if (!string.IsNullOrWhiteSpace(email))
251	        {
252	            return await _clients.Find(c => c.Email == email && !c.IsStudioRentalProfile).FirstOrDefaultAsync();
253	        }
254	
255	        return null;
256	    }
257	}
