82	    {
83	        if (string.IsNullOrWhiteSpace(request.CurrentPassword))
84	            return BadRequest(new { error = "Current password is required." });
85	        if (string.IsNullOrWhiteSpace(request.NewPassword) || request.NewPassword.Length < 8)
86	            return BadRequest(new { error = "New password must be at least 8 characters." });
87	
88	        var userId = CurrentUserId();
