109	    /// <summary>
110	    /// Returns the widget catalog the caller's role may see, plus their saved
111	    /// layout (or a sensible default when none is stored yet).
112	    /// </summary>
113	    [HttpGet("dashboard")]
114	    public async Task<IActionResult> GetDashboard()
115	    {
116	        var userId = CurrentUserId();
117	        if (userId is null) return Unauthorized();
118	
119	        var users = _db.GetCollection<User>("Users");
120	        var user = await users.Find(u => u.Id == userId).FirstOrDefaultAsync();
121	        if (user is null) return NotFound();
122	
123	        var role = string.IsNullOrWhiteSpace(user.Role) ? "Instructor" : user.Role;
124	        var staff = await ResolveLinkedStaffAsync(user);
125	        if (staff is not null) role = MapStaffRoleToUserRole(staff.Role) ?? role;
126	
127	        var catalog = Core.Dashboard.DashboardWidgetCatalog.ForRole(role)
128	            .Select(w => new
129	            {
130	                id = w.Id,
131	                title = w.Title,
132	                category = w.Category,
133	                description = w.Description,
134	                defaultW = w.DefaultW,
135	                defaultH = w.DefaultH,
136	                minW = w.MinW,
137	                minH = w.MinH,
138	            }).ToList();
139	
140	        var layouts = _db.GetCollection<DashboardLayout>("DashboardLayouts");
141	        var saved = await layouts.Find(l => l.UserId == userId).FirstOrDefaultAsync();
142	
143	        object widgets;
144	        if (saved is not null && saved.Widgets.Count > 0)
145	        {
146	            // Defence-in-depth: drop any placement the role is no longer allowed.
147	            widgets = saved.Widgets
148	                .Where(p => Core.Dashboard.DashboardWidgetCatalog.IsAllowed(p.WidgetId, role))
149	                .Select(p => new { widgetId = p.WidgetId, x = p.X, y = p.Y, w = p.W, h = p.H })
150	                .ToList();
151	        }
152	        else
153	        {
154	            widgets = Core.Dashboard.DashboardWidgetCatalog.DefaultLayoutFor(role)
155	                .Select(t => new { widgetId = t.WidgetId, x = t.X, y = t.Y, w = t.W, h = t.H })
156	                .ToList();
157	        }
158	
159	        return Ok(new { role, catalog, widgets });
160	    }
