163	    /// <summary>Persist the caller's dashboard layout (role-filtered server-side).</summary>
164	    [HttpPut("dashboard")]
165	    public async Task<IActionResult> SaveDashboard([FromBody] SaveDashboardRequest request)
166	    {
167	        var userId = CurrentUserId();
168	        if (userId is null) return Unauthorized();
169	
170	        var users = _db.GetCollection<User>("Users");
171	        var user = await users.Find(u => u.Id == userId).FirstOrDefaultAsync();
172	        if (user is null) return NotFound();
173	
174	        var role = string.IsNullOrWhiteSpace(user.Role) ? "Instructor" : user.Role;
175	        var staff = await ResolveLinkedStaffAsync(user);
176	        if (staff is not null) role = MapStaffRoleToUserRole(staff.Role) ?? role;
177	
178	        // Only persist widgets the role is allowed to see — a tampered payload
179	        // can never grant access to a restricted metric.
180	        var placements = (request.Widgets ?? new())
181	            .Where(p => !string.IsNullOrWhiteSpace(p.WidgetId)
182	                        && Core.Dashboard.DashboardWidgetCatalog.IsAllowed(p.WidgetId, role))
183	            .Select(p => new DashboardWidgetPlacement
184	            {
185	                WidgetId = p.WidgetId,
186	                X = p.X, Y = p.Y,
187	                W = System.Math.Max(1, p.W),
188	                H = System.Math.Max(1, p.H),
189	            })
190	            .ToList();
191	
192	        var layouts = _db.GetCollection<DashboardLayout>("DashboardLayouts");
193	        await layouts.UpdateOneAsync(
194	            l => l.UserId == userId,
195	            Builders<DashboardLayout>.Update
196	                .Set(l => l.Widgets, placements)
197	                .Set(l => l.UpdatedAt, System.DateTime.UtcNow)
198	                .SetOnInsert(l => l.UserId, userId)
199	                .SetOnInsert(l => l.CreatedAt, System.DateTime.UtcNow),
200	            new UpdateOptions { IsUpsert = true });
201	
202	        return NoContent();
203	    }
