206	
207	    private string? CurrentUserId()
208	    {
209	        var sub = User.FindFirst(ClaimTypes.NameIdentifier)?.Value
210	                  ?? User.FindFirst("sub")?.Value;
211	        return string.IsNullOrWhiteSpace(sub) ? null : sub;
212	    }
