214	    private async Task<Staff?> ResolveLinkedStaffAsync(User user)
215	    {
216	        var staffCollection = _db.GetCollection<Staff>("Staff");
217	        Staff? staff = null;
218	
219	        if (!string.IsNullOrWhiteSpace(user.StaffId))
220	        {
221	            staff = await staffCollection.Find(s => s.Id == user.StaffId).FirstOrDefaultAsync();
222	        }
223	
224	        if (staff != null) return staff;
225	
226	        var filters = new List<FilterDefinition<Staff>>();
227	        if (!string.IsNullOrWhiteSpace(user.Id))
228	            filters.Add(Builders<Staff>.Filter.Eq(s => s.UserId, user.Id));
229	        if (!string.IsNullOrWhiteSpace(user.Email))
230	            filters.Add(Builders<Staff>.Filter.Eq(s => s.Email, user.Email));
231	        if (filters.Count == 0) return null;
232	
233	        staff = await staffCollection.Find(Builders<Staff>.Filter.Or(filters)).FirstOrDefaultAsync();
234	        if (staff == null || string.IsNullOrWhiteSpace(staff.Id)) return null;
235	
236	        var mappedRole = MapStaffRoleToUserRole(staff.Role) ?? user.Role ?? "Instructor";
237	        await _db.GetCollection<User>("Users").UpdateOneAsync(
238	            u => u.Id == user.Id,
239	            Builders<User>.Update
240	                .Set(u => u.StaffId, staff.Id)
241	                .Set(u => u.Role, mappedRole));
242	
243	        if (string.IsNullOrWhiteSpace(staff.UserId) && !string.IsNullOrWhiteSpace(user.Id))
244	        {
245	            await staffCollection.UpdateOneAsync(
246	                s => s.Id == staff.Id,
247	                Builders<Staff>.Update.Set(s => s.UserId, user.Id));
248	            staff.UserId = user.Id;
249	        }
250	
251	        user.StaffId = staff.Id;
252	        user.Role = mappedRole;
253	        return staff;
254	    }
255	
256	    private static string? MapStaffRoleToUserRole(string? staffRole)
257	    {
258	        return (staffRole ?? string.Empty).Trim().ToUpperInvariant() switch
259	        {
260	            "RECEPTIONIST" => "Receptionist",
261	            "INSTRUCTOR" => "Instructor",
262	            "MANAGER" => "Manager",
263	            "OWNER" => "Owner",
264	            "ACCOUNTANT" => "Accountant",
265	            "SUPERADMIN" => "SuperAdmin",
266	            "FREELANCE" => "Freelance",
267	            _ => null,
268	        };
269	    }
270	}
