1	using MongoDB.Driver;
2	using Microsoft.Extensions.Configuration;
3	using Microsoft.IdentityModel.Tokens;
4	using SoulPilates.Core.DTOs;
5	using SoulPilates.Core.Entities;
6	using SoulPilates.Core.Interfaces;
7	using SoulPilates.Infrastructure.Data;
8	using System.IdentityModel.Tokens.Jwt;
9	using System.Security.Claims;
10	using System.Text;
11	
12	namespace SoulPilates.Services;
13	
14	public class AuthService : IAuthService
15	{
16	    private readonly IMongoCollection<User> _users;
17	    private readonly IMongoCollection<Staff> _staff;
18	    private readonly string _jwtSecret;
19	
20	    public AuthService(MongoDbContext dbContext, IConfiguration config)
21	    {
22	        _users = dbContext.GetCollection<User>("Users");
23	        _staff = dbContext.GetCollection<Staff>("Staff");
24	        _jwtSecret = config["JwtSettings:Secret"] ?? throw new Exception("Jwt secret not found");
25	    }
26	
27	    public async Task<LoginResponse?> AuthenticateAsync(LoginRequest request)
28	    {
29	        // Case-insensitive email lookup. Emails are stored lowercased by the
30	        // seeder, but sign-in input (especially iOS autofill) may arrive with
31	        // different casing. Anchor + escape so the value is matched literally,
32	        // not as a user-supplied regex.
33	        var emailPattern = "^" + System.Text.RegularExpressions.Regex.Escape(request.Email?.Trim() ?? "") + "$";
34	        var emailFilter = Builders<User>.Filter.Regex(
35	            u => u.Email,
36	            new MongoDB.Bson.BsonRegularExpression(emailPattern, "i"));
37	        var user = await _users.Find(emailFilter).FirstOrDefaultAsync();
38	        if (user == null || !PasswordHasher.Verify(request.Password, user.PasswordHash)) return null;
39	
40	        var linkedStaff = await ResolveLinkedStaffAsync(user);
41	        var effectiveRole = ResolveEffectiveRole(user, linkedStaff);
42	
43	        var tokenHandler = new JwtSecurityTokenHandler();
44	        var key = Encoding.ASCII.GetBytes(_jwtSecret);
45	
46	        // Base claims — every authenticated user carries these.
47	        // P3-S09: instructor users additionally carry a `staff_id`
48	        // claim so the InstructorController can resolve the linked
49	        // Staff row without re-querying the Users collection on
50	        // every request. Conditional emission keeps the token small
51	        // for Admin/Owner accounts that have no Staff link.
52	        var claims = new List<Claim>
53	        {
54	            new(ClaimTypes.NameIdentifier, user.Id ?? ""),
55	            new(ClaimTypes.Role, effectiveRole),
56	            new(ClaimTypes.Email, user.Email),
57	        };
58	        if (!string.IsNullOrWhiteSpace(user.StaffId))
59	            claims.Add(new Claim("staff_id", user.StaffId));
60	
61	        // Per-user admin-module access. When the account is in custom-access
62	        // mode, AllowedAdminModules is the AUTHORITATIVE set (fully replaces the
63	        // role defaults) and we flag that with `access_mode=custom` so the
64	        // Module:{key} policy stops falling back to the role. Otherwise the
65	        // module claims simply ADD to the role defaults.
66	        if (user.UseCustomModuleAccess)
67	            claims.Add(new Claim("access_mode", "custom"));
68	
69	        foreach (var moduleKey in (user.AllowedAdminModules ?? new List<string>())
70	                     .Where(m => !string.IsNullOrWhiteSpace(m))
71	                     .Select(m => m.Trim().ToLowerInvariant())
72	                     .Distinct())
73	        {
74	            claims.Add(new Claim("module", moduleKey));
75	        }
76	
77	        var tokenDescriptor = new SecurityTokenDescriptor
78	        {
79	            Subject = new ClaimsIdentity(claims),
80	            Expires = DateTime.UtcNow.AddDays(7),
81	            SigningCredentials = new SigningCredentials(new SymmetricSecurityKey(key), SecurityAlgorithms.HmacSha256Signature)
82	        };
83	
84	        var token = tokenHandler.CreateToken(tokenDescriptor);
85	
86	        return new LoginResponse
87	        {
88	            Token = tokenHandler.WriteToken(token),
89	            UserRole = effectiveRole,
90	            StaffId = user.StaffId,
91	            MustChangePassword = user.MustChangePassword,
92	        };
93	    }
94	
95	    public async Task<bool> ChangePasswordAsync(string userId, string newPassword)
96	    {
97	        var update = Builders<User>.Update
98	            .Set(u => u.PasswordHash, PasswordHasher.Hash(newPassword))
99	            .Set(u => u.MustChangePassword, false);
100	        var result = await _users.UpdateOneAsync(u => u.Id == userId, update);
101	        return result.MatchedCount > 0;
102	    }
103	
104	    private string ResolveEffectiveRole(User user, Staff? staff)
105	    {
106	        var mapped = MapStaffRoleToUserRole(staff?.Role);
107	        if (!string.IsNullOrWhiteSpace(mapped)) return mapped;
108	
109	        return string.IsNullOrWhiteSpace(user.Role) ? "Instructor" : user.Role;
110	    }
111	
112	    private async Task<Staff?> ResolveLinkedStaffAsync(User user)
113	    {
114	        Staff? staff = null;
115	
116	        if (!string.IsNullOrWhiteSpace(user.StaffId))
117	        {
118	            staff = await _staff.Find(s => s.Id == user.StaffId).FirstOrDefaultAsync();
119	        }
120	
121	        if (staff != null) return staff;
122	
123	        var filters = new List<FilterDefinition<Staff>>();
124	        if (!string.IsNullOrWhiteSpace(user.Id))
125	            filters.Add(Builders<Staff>.Filter.Eq(s => s.UserId, user.Id));
126	        if (!string.IsNullOrWhiteSpace(user.Email))
127	            filters.Add(Builders<Staff>.Filter.Eq(s => s.Email, user.Email));
128	        if (filters.Count == 0) return null;
129	
130	        staff = await _staff.Find(Builders<Staff>.Filter.Or(filters)).FirstOrDefaultAsync();
131	        if (staff == null || string.IsNullOrWhiteSpace(staff.Id)) return null;
132	
133	        var mappedRole = MapStaffRoleToUserRole(staff.Role) ?? user.Role ?? "Instructor";
134	        await _users.UpdateOneAsync(
135	            u => u.Id == user.Id,
136	            Builders<User>.Update
137	                .Set(u => u.StaffId, staff.Id)
138	                .Set(u => u.Role, mappedRole));
139	
140	        if (string.IsNullOrWhiteSpace(staff.UserId) && !string.IsNullOrWhiteSpace(user.Id))
141	        {
142	            await _staff.UpdateOneAsync(
143	                s => s.Id == staff.Id,
144	                Builders<Staff>.Update.Set(s => s.UserId, user.Id));
145	            staff.UserId = user.Id;
146	        }
147	
148	        user.StaffId = staff.Id;
149	        user.Role = mappedRole;
150	        return staff;
151	    }
152	
153	    private static string? MapStaffRoleToUserRole(string? staffRole)
154	    {
155	        return (staffRole ?? string.Empty).Trim().ToUpperInvariant() switch
156	        {
157	            "RECEPTIONIST" => "Receptionist",
158	            "INSTRUCTOR" => "Instructor",
159	            "HEADINSTRUCTOR" => "HeadInstructor",
160	            "MANAGER" => "Manager",
161	            "OWNER" => "Owner",
162	            "ACCOUNTANT" => "Accountant",
163	            "SUPERADMIN" => "SuperAdmin",
164	            "FREELANCE" => "Freelance",
165	            _ => null,
166	        };
167	    }
168	}
