using MongoDB.Bson;
using MongoDB.Bson.Serialization.Attributes;
using System;

namespace SoulPilates.Core.Entities;

/// <summary>
/// A single dated internal staff note attached to a <see cref="Client"/>. Stored
/// as a sub-document in the client's <see cref="Client.Notes"/> array (Mongo is
/// schemaless — no migration; existing client documents simply deserialize to an
/// empty list). These are INTERNAL staff notes and are never surfaced to the
/// customer / portal.
/// </summary>
public class ClientNote
{
    /// <summary>Stable per-note identifier (a fresh ObjectId string), used by the
    /// delete endpoint to target one note.</summary>
    [BsonId]
    [BsonRepresentation(BsonType.ObjectId)]
    public string? Id { get; set; }

    /// <summary>The note body as typed by the staff member (trimmed, capped at
    /// 4000 chars by the controller before it ever reaches here).</summary>
    public string Text { get; set; } = null!;

    /// <summary>Id of the staff <c>User</c> who wrote the note. Kept as a plain
    /// string (not an ObjectId representation) so a note can always be written
    /// even if the caller's identity is unusual, and so the author-match check in
    /// the delete path can never throw at serialization time.</summary>
    public string? AuthorId { get; set; }

    /// <summary>Display name of the author, snapshotted at write time so the feed
    /// still reads correctly if the user is later renamed or removed.</summary>
    public string? AuthorName { get; set; }

    /// <summary>Server UTC timestamp the note was created. The UI formats this in
    /// studio-local time (Asia/Ho_Chi_Minh) for display.</summary>
    public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
}

