    /// <summary>
    /// Append a dated staff note to a client's notes log via a targeted
    /// <c>$push</c> (never a full document replace, so no other field is touched).
    /// Returns the created note, or <c>null</c> if the client does not exist.
    /// </summary>
    Task<ClientNote?> AddNoteAsync(string clientId, string text, string? authorId, string? authorName);

    /// <summary>
    /// Delete one staff note. Permitted when the requester is the note's author
    /// OR an admin-tier user. Returns a result distinguishing not-found from a
    /// permission refusal so the controller can map it to 404 vs 403.
    /// </summary>
    Task<NoteDeleteResult> DeleteNoteAsync(string clientId, string noteId, string? requesterId, bool isAdmin);
}

/// <summary>Outcome of a staff-note delete attempt.</summary>
public enum NoteDeleteResult
{
    /// <summary>The client or the note id was not found.</summary>
    NotFound,
    /// <summary>The requester is neither the author nor an admin.</summary>
    Forbidden,
    /// <summary>The note was removed.</summary>
    Deleted,
}

public async Task<ClientNote?> AddNoteAsync(string clientId, string text, string? authorId, string? authorName)
{
    var note = new ClientNote
    {
        Id = MongoDB.Bson.ObjectId.GenerateNewId().ToString(),
        Text = text,
        AuthorId = string.IsNullOrWhiteSpace(authorId) ? null : authorId,
        AuthorName = string.IsNullOrWhiteSpace(authorName) ? null : authorName,
        CreatedAt = DateTime.UtcNow,
    };

    // Targeted $push — never a full ReplaceOne — so appending a note can't
    // clobber any server-managed client state.
    var result = await _clients.UpdateOneAsync(
        c => c.Id == clientId,
        Builders<Client>.Update.Push(c => c.Notes, note));

    return result.MatchedCount == 0 ? null : note;
}

public async Task<NoteDeleteResult> DeleteNoteAsync(string clientId, string noteId, string? requesterId, bool isAdmin)
{
    var client = await _clients.Find(c => c.Id == clientId).FirstOrDefaultAsync();
    if (client == null) return NoteDeleteResult.NotFound;

    var note = client.Notes?.FirstOrDefault(n => n.Id == noteId);
    if (note == null) return NoteDeleteResult.NotFound;

    var isAuthor = !string.IsNullOrEmpty(note.AuthorId)
        && !string.IsNullOrEmpty(requesterId)
        && note.AuthorId == requesterId;
    if (!isAuthor && !isAdmin) return NoteDeleteResult.Forbidden;

    // Targeted $pull by note id — leaves every other note and field intact.
    await _clients.UpdateOneAsync(
        c => c.Id == clientId,
        Builders<Client>.Update.PullFilter(c => c.Notes, n => n.Id == noteId));

    return NoteDeleteResult.Deleted;
}

