// ─────────────────────────────────────────────────────────────────────
//  Dated staff notes — an internal comments feed on the client profile.
//  Not visible to the customer. A note records the authoring staff user's
//  id + name and a server UTC timestamp. Delete is limited to the note's
//  author or an admin-tier user.
// ─────────────────────────────────────────────────────────────────────

/// <summary>List a client's staff notes, newest first. Each note carries a
/// <c>canDelete</c> flag computed for the current caller.</summary>
[HttpGet("{id}/notes")]
public async Task<IActionResult> GetNotes(string id)
{
    var c = await _clientService.GetClientByIdAsync(id);
    if (c == null) return NotFound();

    var me = CurrentStaffUserId();
    var admin = IsAdminTier();
    var notes = (c.Notes ?? new List<ClientNote>())
        .OrderByDescending(n => n.CreatedAt)
        .Select(n => ToNoteDto(n, me, admin))
        .ToList();
    return Ok(notes);
}

/// <summary>Append a note to a client's log. Records the current staff user's
/// id/name + a server timestamp. Validates non-empty and caps length.</summary>
[HttpPost("{id}/notes")]
public async Task<IActionResult> AddNote(string id, [FromBody] AddClientNoteDto body)
{
    var text = body?.text?.Trim();
    if (string.IsNullOrEmpty(text))
        return BadRequest(new { error = "Note text is required." });
    if (text.Length > 4000)
        return BadRequest(new { error = "Note is too long (maximum 4000 characters)." });

    var userId = CurrentStaffUserId();
    if (userId is null) return Unauthorized();

    var authorName = await ResolveUserNameAsync(userId) ?? "Staff";
    var note = await _clientService.AddNoteAsync(id, text, userId, authorName);
    if (note == null) return NotFound();

    // The author can always delete a note they just created.
    return Ok(ToNoteDto(note, userId, IsAdminTier()));
}

/// <summary>Delete a note. Allowed for the note's author OR an admin-tier
/// user; 403 otherwise, 404 if the client/note is unknown.</summary>
[HttpDelete("{id}/notes/{noteId}")]
public async Task<IActionResult> DeleteNote(string id, string noteId)
{
    var userId = CurrentStaffUserId();
    if (userId is null) return Unauthorized();

    var result = await _clientService.DeleteNoteAsync(id, noteId, userId, IsAdminTier());
    return result switch
    {
        NoteDeleteResult.Deleted => NoContent(),
        NoteDeleteResult.Forbidden => StatusCode(403, new { error = "You can only delete your own notes." }),
        _ => NotFound(),
    };
}

/// <summary>Current authenticated staff user's id, or null.</summary>
private string? CurrentStaffUserId()
{
    var sub = User.FindFirst(ClaimTypes.NameIdentifier)?.Value ?? User.FindFirst("sub")?.Value;
    return string.IsNullOrWhiteSpace(sub) ? null : sub;
}

/// <summary>Admin-tier roles that may moderate (delete) any staff note.</summary>
private bool IsAdminTier()
    => User.IsInRole("Admin") || User.IsInRole("Owner") || User.IsInRole("SuperAdmin");

/// <summary>Resolve a staff user's display name from the Users collection.</summary>
private async Task<string?> ResolveUserNameAsync(string userId)
{
    var users = _db.GetCollection<User>("Users");
    var u = await users.Find(x => x.Id == userId).FirstOrDefaultAsync();
    return string.IsNullOrWhiteSpace(u?.Name) ? null : u.Name;
}

private static ClientNoteDto ToNoteDto(ClientNote n, string? me, bool isAdmin) => new()
{
    id = n.Id,
    text = n.Text,
    authorId = n.AuthorId,
    authorName = n.AuthorName,
    createdAt = n.CreatedAt,
    canDelete = isAdmin || (!string.IsNullOrEmpty(n.AuthorId) && n.AuthorId == me),
};

