/// <summary>Request body for <c>PUT api/client/{id}/email-subscription</c>.</summary>
public class EmailSubscriptionUpdateDto
{
    /// <summary>True to (re)subscribe the client to check-in emails, false to opt out.</summary>
    public bool subscribed { get; set; } = true;
}

/// <summary>Request body for <c>POST api/client/{id}/notes</c>.</summary>
public class AddClientNoteDto
{
    /// <summary>The note text (required, trimmed, max 4000 chars).</summary>
    public string? text { get; set; }
}

/// <summary>A staff note as returned to the client-profile notes feed.</summary>
public class ClientNoteDto
{
    public string? id { get; set; }
    public string? text { get; set; }
    public string? authorId { get; set; }
    public string? authorName { get; set; }
    public System.DateTime createdAt { get; set; }
    /// <summary>Whether the current caller may delete this note (author or admin).</summary>
    public bool canDelete { get; set; }
}

  window.openAddPackage = openAddPackage;
  window.submitAddPackage = submitAddPackage;

  // ── Staff notes (internal, dated comments feed) ──────────────────────
  const notesList = document.getElementById("notesList");
  const noteInput = document.getElementById("noteInput");
  const addNoteBtn = document.getElementById("addNoteBtn");
  const noteCharCount = document.getElementById("noteCharCount");
  const NOTE_TZ = "Asia/Ho_Chi_Minh"; // studio-local time

  function fmtNoteDate(iso) {
    try {
      return new Date(iso).toLocaleString("en-GB", {
        timeZone: NOTE_TZ,
        day: "numeric",
        month: "short",
        year: "numeric",
        hour: "2-digit",
        minute: "2-digit",
        hour12: false,
      });
    } catch {
      return "";
    }
  }
  function escNote(s) {
    return String(s ?? "").replace(
      /[&<>"']/g,
      (c) =>
        ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c],
    );
  }
  function noteInitials(name) {
    return (
      (name || "?")
        .split(" ")
        .filter(Boolean)
        .map((n) => n[0])
        .join("")
        .substring(0, 2)
        .toUpperCase() || "?"
    );
  }
  function renderNotes(notes) {
    if (!notesList) return;
    if (!notes || notes.length === 0) {
      notesList.innerHTML = `<div class="text-muted text-sm" style="text-align:center;padding:24px;">No notes yet. Add the first one above.</div>`;
      return;
    }
    notesList.innerHTML = notes
      .map(
        (n) => `
      <div style="display:flex;gap:10px;padding:12px;border:1px solid var(--color-border);border-radius:var(--radius-md);background:var(--color-surface);">
        <div style="flex-shrink:0;width:32px;height:32px;border-radius:50%;background:var(--color-brand-accent-soft);border:1px solid var(--color-brand-accent);display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:600;color:var(--color-brand-accent);">${escNote(noteInitials(n.authorName))}</div>
        <div style="flex:1;min-width:0;">
          <div style="display:flex;align-items:baseline;justify-content:space-between;gap:8px;">
            <span style="font-weight:600;font-size:13px;color:var(--color-text-primary);">${escNote(n.authorName || "Staff")}</span>
            <span class="text-muted text-sm" style="white-space:nowrap;">${escNote(fmtNoteDate(n.createdAt))}</span>
          </div>
          <div style="margin-top:4px;font-size:13px;color:var(--color-text-secondary);white-space:pre-wrap;word-break:break-word;">${escNote(n.text)}</div>
        </div>
        ${
          n.canDelete
            ? `<button type="button" title="Delete note" onclick="deleteClientNote('${escNote(n.id)}')" style="flex-shrink:0;background:transparent;border:none;color:var(--color-text-muted);cursor:pointer;font-size:15px;line-height:1;padding:2px;">🗑</button>`
            : ""
        }
      </div>`,
      )
      .join("");
  }
  function loadNotes() {
    if (!notesList) return;
    fetch(`${API}/api/client/${clientId}/notes`, {
      headers: { Authorization: "Bearer " + token },
    })
      .then((r) => (r.ok ? r.json() : Promise.reject(new Error(`Failed (${r.status})`))))
      .then(renderNotes)
      .catch(() => {
        notesList.innerHTML = `<div class="text-muted text-sm" style="text-align:center;padding:24px;">Could not load notes.</div>`;
      });
  }
  if (noteInput && noteCharCount) {
    noteInput.addEventListener("input", () => {
      noteCharCount.textContent = `${noteInput.value.length} / 4000`;
    });
  }
  window.submitClientNote = async function () {
    const text = (noteInput?.value || "").trim();
    if (!text) {
      noteInput?.focus();
      return;
    }
    if (!addNoteBtn) return;
    addNoteBtn.disabled = true;
    const orig = addNoteBtn.textContent;
    addNoteBtn.textContent = "Adding…";
    try {
      const res = await fetch(`${API}/api/client/${clientId}/notes`, {
        method: "POST",
        headers: {
          Authorization: "Bearer " + token,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ text }),
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(data.error || `Failed (${res.status})`);
      noteInput.value = "";
      if (noteCharCount) noteCharCount.textContent = "0 / 4000";
      loadNotes();
      (window.showToast || (() => {}))("Note added.", "success");
    } catch (e) {
      (window.showToast || ((m) => alert(m)))(
        e.message || "Could not add the note.",
        "error",
      );
    } finally {
      addNoteBtn.disabled = false;
      addNoteBtn.textContent = orig;
    }
  };
  window.deleteClientNote = async function (noteId) {
    if (!noteId) return;
    if (!confirm("Delete this note? This cannot be undone.")) return;
    try {
      const res = await fetch(`${API}/api/client/${clientId}/notes/${noteId}`, {
        method: "DELETE",
        headers: { Authorization: "Bearer " + token },
      });
      if (!res.ok && res.status !== 204) {
        const data = await res.json().catch(() => ({}));
        throw new Error(data.error || `Failed (${res.status})`);
      }
      loadNotes();
      (window.showToast || (() => {}))("Note deleted.", "success");
    } catch (e) {
      (window.showToast || ((m) => alert(m)))(
        e.message || "Could not delete the note.",
        "error",
      );
    }
  };
  loadNotes();
</script>

