const columnId = "cmsavfvin000khla4anofdbxt";
const last = await prisma.card.findFirst({ where:{ columnId }, orderBy:{ position:"desc" }, select:{ position:true } });
const position = (last?.position ?? -1) + 1;
const card = await prisma.card.create({ data:{
  boardId, columnId, title:"Dated notes on client profile",
  type:"FEATURE", priority:"NORMAL", assignee:"claude", position,
  description:"Internal, dated staff-notes / comments feed on the Soul Pilates customer profile (.NET API + Astro). Notes stored on the Client Mongo document as a subdocument array; author + server UTC timestamp recorded. Delete limited to author or admin-tier.",
}});
const comment = await prisma.cardComment.create({ data:{
  cardId: card.id, authorName:"Claude",
